def main():
    assert set(P.keys()) == set(EXPECTED), (set(P.keys()) ^ set(EXPECTED))
    os.makedirs(BASE, exist_ok=True)
    for cid in EXPECTED:
        d = P[cid]
        rec = {"case_id": cid, "prediction_text": d["prediction_text"],
               "basis": d["basis"], "confidence": d["confidence"], "trigger": d["trigger"]}
        path = os.path.join(BASE, cid + ".json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
    # verify each by exact open
    ok = 0
    for cid in EXPECTED:
        path = os.path.join(BASE, cid + ".json")
        with open(path, encoding="utf-8") as f:
            rec = json.load(f)
        assert rec["case_id"] == cid
        for k in ("prediction_text", "basis", "confidence", "trigger"):
            assert k in rec and rec[k] not in (None, ""), (cid, k)
        for k in ("changed_main", "reserve_used", "disputed", "reason"):
            assert k in rec["trigger"], (cid, k)
        assert isinstance(rec["confidence"], (int, float)) and 0 <= rec["confidence"] <= 1
        ok += 1
    tc = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
    for cid in EXPECTED:
        with open(os.path.join(BASE, cid + ".json"), encoding="utf-8") as f:
            tr = json.load(f)["trigger"]
        for k in tc:
            tc[k] += 1 if tr[k] else 0
    print("written_and_verified:", ok)
    print("trigger_counts:", tc)

if __name__ == "__main__":
    main()
